record.field:
{
                "type": "object",
                "properties": {
                    "model": {"type": "string", "description": "Odoo model name"},
                    "res_id": {"type": "integer", "description": "Record ID"},
                    "values": {"type": "object", "description": "Field values to update"}
                },
                "required": ["model", "res_id", "values"]
            }

{
                "type": "object",
                "properties": {
                    "model": {"type": "string", "description": "Odoo model name (e.g. project.task)"},
                    "res_id": {"type": "integer", "description": "ID of the record to modify"},
                    "field": {"type": "string", "description": "Name of the relational field (many2many or many2one) to unlink from"},
                    "related_ids": {"type": "array", "items": {"type": "integer"}, "description": "List of related record IDs to remove from a many2many field (not required for many2one)"}
                },
                "required": ["model", "res_id", "field"]
            }

{
                "type": "object",
                "properties": {
                    "model": {"type": "string", "description": "Odoo model technical name (e.g. res.partner, sale.order)"},
                    "res_id": {"type": "integer", "description": "ID of the record to permanently delete"}
                },
                "required": ["model", "res_id"]
            }

{
                "type": "object",
                "properties": {
                    "model": {"type": "string", "description": "Odoo model technical name (e.g. sale.order, res.partner)"},
                    "question": {"type": "string", "description": "The question or analysis task to perform on the fetched records"},
                    "domain": {"type": "array", "description": "Optional Odoo domain to filter records (e.g. [['state', '=', 'sale']])"},
                    "fields": {"type": "array", "items": {"type": "string"}, "description": "Optional list of field names to include. If omitted, key fields are selected automatically."},
                    "limit": {"type": "integer", "description": "Maximum number of records to fetch (default: 20)"},
                    "provider": {"type": "string", "description": "Optional AI provider name. Defaults to the first active provider."},
                    "ai_model": {"type": "string", "description": "Optional model name to use for the AI call (e.g. gpt-4o, claude-sonnet-4-6)."}
                },
                "required": ["model", "question"]
            }

{
                "type": "object",
                "properties": {
                    "prompt": {"type": "string", "description": "The message or question to send to the AI"},
                    "provider": {"type": "string", "description": "Optional provider name (e.g. OpenAI, Anthropic, Local Ollama). Defaults to first active provider."},
                    "model": {"type": "string", "description": "Optional model name (e.g. gpt-4o, claude-sonnet-4-6, llama3). Defaults to provider default."}
                },
                "required": ["prompt"]
            }
